files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e8e8e8;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --accent-pressed: #c62a47;
  --border: #2a2a4a;
  --focus: #ffd166;
  --radius: 12px;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background-image: radial-gradient(circle at 20% 50%, #1f1f3a 0%, transparent 50%),
                    radial-gradient(circle at 80% 20%, #2a1a3a 0%, transparent 50%);
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 640px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  border: 1px solid var(--border);
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 4px;
  letter-spacing: -0.02em;
}

.subtitle {
  font-size: 0.95rem;
  color: #9a9ab0;
  margin-bottom: 24px;
}

.palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  margin-bottom: 24px;
}

.swatch {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--border);
  transition: transform 0.15s ease;
}

.swatch:hover {
  transform: translateY(-2px);
}

.swatch-color {
  height: 100px;
  width: 100%;
  transition: background-color 0.3s ease;
}

.swatch-info {
  background: #0f0f1a;
  padding: 8px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.hex-label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  font-family: ui-monospace, 'Cascadia Code', monospace;
  color: var(--text);
  text-transform: uppercase;
}

.lock-btn {
  background: none;
  border: 1px solid var(--border);
  border-radius: 4px;
  color: #9a9ab0;
  font-size: 0.85rem;
  padding: 3px 8px;
  cursor: pointer;
  transition: all 0.15s ease;
  line-height: 1;
  min-width: 32px;
  min-height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.lock-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.lock-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.lock-btn:active {
  transform: scale(0.95);
}

.lock-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.generate-btn {
  display: block;
  width: 100%;
  padding: 14px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  letter-spacing: 0.02em;
}

.generate-btn:hover {
  background: var(--accent-hover);
}

.generate-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.generate-btn:active {
  background: var(--accent-pressed);
  transform: scale(0.98);
}

@media (max-width: 480px) {
  .palette {
    grid-template-columns: repeat(5, 1fr);
    gap: 6px;
  }
  .swatch-color {
    height: 70px;
  }
  .hex-label {
    font-size: 0.65rem;
  }
  .lock-btn {
    font-size: 0.75rem;
    padding: 2px 4px;
    min-width: 26px;
    min-height: 24px;
  }
  .card {
    padding: 16px;
  }
}

(function () {
  'use strict';

  const palette = document.getElementById('palette');
  const generateBtn = document.getElementById('generateBtn');
  const SWATCH_COUNT = 5;

  let colors = [];
  let locked = new Array(SWATCH_COUNT).fill(false);

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const a = s * Math.min(l, 1 - l);
    const f = (n) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return '#' + f(0) + f(8) + f(4);
  }

  function generateHarmonious() {
    const baseHue = Math.random() * 360;
    const schemes = [
      [0, 72, 144, 216, 288],
      [0, 30, 60, 180, 240],
      [0, 40, 80, 160, 200],
      [0, 120, 240, 60, 180],
      [0, 20, 40, 60, 80]
    ];
    const scheme = schemes[Math.floor(Math.random() * schemes.length)];
    const saturation = 55 + Math.random() * 35;
    const lightnessBase = 45 + Math.random() * 15;

    return scheme.map((offset, i) => {
      const hue = (baseHue + offset) % 360;
      const l = Math.min(85, Math.max(25, lightnessBase + (i % 2 === 0 ? 8 : -8)));
      return hslToHex(hue, saturation, l);
    });
  }

  function render() {
    palette.innerHTML = '';
    colors.forEach((hex, i) => {
      const swatch = document.createElement('div');
      swatch.className = 'swatch';

      const colorDiv = document.createElement('div');
      colorDiv.className = 'swatch-color';
      colorDiv.style.backgroundColor = hex;
      colorDiv.setAttribute('role', 'img');
      colorDiv.setAttribute('aria-label', 'Color ' + hex);

      const info = document.createElement('div');
      info.className = 'swatch-info';

      const hexLabel = document.createElement('span');
      hexLabel.className = 'hex-label';
      hexLabel.textContent = hex;

      const lockBtn = document.createElement('button');
      lockBtn.type = 'button';
      lockBtn.className = 'lock-btn';
      lockBtn.setAttribute('aria-pressed', locked[i] ? 'true' : 'false');
      lockBtn.setAttribute('aria-label', (locked[i] ? 'Unlock' : 'Lock') + ' color ' + hex);
      lockBtn.textContent = locked[i] ? '\uD83D\uDD12' : '\uD83D\uDD13';

      lockBtn.addEventListener('click', () => {
        locked[i] = !locked[i];
        lockBtn.setAttribute('aria-pressed', locked[i] ? 'true' : 'false');
        lockBtn.setAttribute('aria-label', (locked[i] ? 'Unlock' : 'Lock') + ' color ' + colors[i]);
        lockBtn.textContent = locked[i] ? '\uD83D\uDD12' : '\uD83D\uDD13';
      });

      info.appendChild(hexLabel);
      info.appendChild(lockBtn);
      swatch.appendChild(colorDiv);
      swatch.appendChild(info);
      palette.appendChild(swatch);
    });
  }

  function generate() {
    const fresh = generateHarmonious();
    colors = colors.length === SWATCH_COUNT
      ? fresh.map((c, i) => (locked[i] ? colors[i] : c))
      : fresh;
    render();
  }

  generateBtn.addEventListener('click', generate);

  generate();
})();
